fun Binary_Search_Recursive(@init<table> collection, target, low, high):
    // Base case: element not found
    @mark<low, outline, yellow> @mark<high, outline, yellow> if (low > high):
        @log<warn, "Not found"> return -1
    end if

    // Calculate middle index
    @mark<low, outline, yellow> @mark<high, outline, yellow> mid = floor((low + high) / 2)

    // Get value at the middle
    @mark<mid, highlight, yellow> val = collection[mid]

    // Element found at mid
    @mark<mid, text, fg> if (val == target):
        @mark<mid, highlight, green> return mid
    end if

    // Target is in the left half
    @mark<mid, text, fg> if (val > target):
        @mark<high, outline, yellow> high = mid - 1
        @mark<high, outline, yellow> return Binary_Search_Recursive(collection, target, low, high)
    end if

    // Target is in the right half
    @mark<mid, text, fg> @mark<low, outline, yellow> low = mid + 1
    @mark<low, outline, yellow> return Binary_Search_Recursive(collection, target, low, high)
