fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)

    // Set lower and upper bounds for the range of unsorted elements
    lower_bound = 0
    upper_bound = n - 1

    // Continue sorting while the range is valid
    while (lower_bound < upper_bound):
        swapped = False

        // Pass from left to right
        @mark<lower_bound, outline, yellow> for (i = lower_bound; i < upper_bound; i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap(array[i], array[i + 1])
                swapped = True
            end if
        end for

        // Reduce the upper bound since the largest element is now at the end
        upper_bound -= 1

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if

        // Pass from right to left
        @mark<upper_bound, outline, yellow> for (i = upper_bound; i > lower_bound; i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap(array[i], array[i - 1])
                swapped = True
            end if
        end for

        // Increase the lower bound since the smallest element is now at the beginning
        lower_bound += 1

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if
    end while

    return array
end fun

