fun Partition_Even_Odd(@init<table> array):
    // Initialize two pointers
    left = 0
    right = length(array) - 1

    // Loop until pointers meet
    while (left < right):
        // Move left pointer to find odd number
        while (left < right):
            @mark<left, outline, yellow> if (array[left] % 2 == 0):
                left += 1
            else:
                break
            end if
        end while

        // Move right pointer to find even number
        while (left < right):
            @mark<right, outline, yellow> if (array[right] % 2 == 1):
                right -= 1
            else:
                break
            end if
        end while

        // If both pointers found their targets, swap them
        if (left < right):
            @mark<left, highlight, green> @mark<right, highlight, green> swap(array[left], array[right])
            left += 1
            right -= 1
        end if
    end while

    return array
end fun

