fun Interpolation_Search(@init<table> collection, target, size):
    low = 0
    high = size - 1

    while (low <= high):
        // Check for division by zero
        @mark<low, outline, yellow> if (collection[high] == collection[low]):
            @mark<low, highlight, red> if (collection[low] == target):
                @mark<low, highlight, green> return low
            end if
            @log<warn, "Not found"> return -1
        end if

        // Calculate probe position using interpolation formula
        @mark<high, outline, yellow> pos = low + floor(((target - collection[low]) * (high - low)) / (collection[high] - collection[low]))

        // Ensure pos is within bounds
        @mark<pos, text, fg> if (pos < low or pos > high):
            @log<warn, "Not found"> return -1
        end if

        // Get value at the probe position
        @mark<pos, highlight, yellow> val = collection[pos]

        if (val == target):
            @mark<pos, highlight, green> return pos
        end if

        if (val < target):
            @mark<low, outline, yellow> low = pos + 1
        end if

        if (val > target):
            @mark<high, outline, yellow> high = pos - 1
        end if
    end while

    @log<warn, "Not found"> return -1
end fun

