fun Max_Subarray_Sum(@init<table> nums):
    n = length(nums)

    // Initialize variables to track maximum sum ending at current position
    // and overall maximum sum seen so far
    @mark<0, outline, yellow> maxEndingHere = nums[0]
    @mark<0, highlight, green> maxSoFar = nums[0]

    // Iterate through the rest of the array
    for (i = 1; i < n; i += 1):
        // Either extend the existing subarray or start a new one
        @mark<i, outline, yellow> if (maxEndingHere + nums[i] > nums[i]):
            @mark<i, text, fg> maxEndingHere = maxEndingHere + nums[i]
        else:
            @mark<i, text, fg> maxEndingHere = nums[i]
        end if

        // Update the overall maximum if needed
        @mark<i, highlight, green> if (maxEndingHere > maxSoFar):
            @mark<i, text, fg> maxSoFar = maxEndingHere
        end if
    end for

    @log<"Maximum subarray sum: "> return maxSoFar
end fun

