fun Merge_Sort(@init<table> array):
    n = length(array)
    temp = arr(n)  // temporary array for merging
    Merge_Sort_Helper(array, temp, 0, n - 1)
    return array
end fun

fun Merge_Sort_Helper(@init<table> array, @init<table> temp, low, high):
    if (low < high):
        mid = floor((low + high) / 2)

        // Recursively sort first half
        @mark<mid, outline, yellow> Merge_Sort_Helper(array, temp, low, mid)

        // Recursively sort second half
        @mark<mid, outline, yellow> Merge_Sort_Helper(array, temp, mid + 1, high)

        // Merge the two halves
        @mark<low, highlight, green> Merge(array, temp, low, mid, high)
    end if
end fun

fun Merge(@init<table> array, @init<table> temp, low, mid, high):
    // Copy data to temporary array
    for (i = low, i <= high, i += 1):
        @mark<i, outline, yellow> temp[i] = array[i]
    end for

    i = low      // Initial index of first subarray
    j = mid + 1  // Initial index of second subarray
    k = low      // Initial index of merged array

    // Merge the temp arrays back
    while ((i <= mid) and (j <= high)):
        @mark<i, outline, yellow> if (temp[i] <= temp[j]):
            @mark<k, highlight, green> array[k] = temp[i]
            i += 1
        else:
            @mark<k, highlight, green> array[k] = temp[j]
            j += 1
        end if
        k += 1
    end while

    // Copy remaining elements of temp[i..mid], if any
    while (i <= mid):
        @mark<i, outline, yellow> @mark<k, highlight, green> array[k] = temp[i]
        i += 1
        k += 1
    end while

    // Copy remaining elements of temp[j..high], if any
    while (j <= high):
        @mark<j, outline, yellow> @mark<k, highlight, green> array[k] = temp[j]
        j += 1
        k += 1
    end while
end fun

