fun Move_ZerosToEnd(@init<table> array):
    n = length(array)
    // Index to place the next non-zero element
    @mark<0, outline, yellow> writeIndex = 0

    // First pass: move all non-zero elements to the front
    for (i = 0, i < n, i += 1):
        @mark<i, outline, yellow> if (array[i] != 0):
            @mark<i, highlight, green> swap(array[writeIndex], array[i])
            writeIndex += 1
        end if
    end for

    // At this point, all non-zero elements are at the beginning,
    // and writeIndex points to the first zero position.
    // Second pass: fill the rest with zeros
    for (i = writeIndex, i < n, i += 1):
        @mark<i, outline, yellow> array[i] = 0
    end for

    return array
end fun

